"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["6813"],{93456(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.conformidade_legal_insuficiente","status":422,"titulo":"Processo n\xe3o conforme \xe0s obrigatoriedades legais vigentes"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.conformidade_legal_insuficiente","requisitos":["UNI-REQ-0018"],"oQueAconteceu":["Antes de congelar a configura\xe7\xe3o \u2014 seja publicando, seja retificando o\\nprocesso j\xe1 publicado \u2014, o sistema resolve as\\nobrigatoriedades legais vigentes para o tipo do processo **na data de in\xedcio\\ndo per\xedodo de inscri\xe7\xe3o declarado no comando** (`periodoInscricaoInicio`), e\\navalia cada uma contra a configura\xe7\xe3o montada. Se qualquer regra reprova, a\\ntransi\xe7\xe3o \xe9 recusada antes da canonicaliza\xe7\xe3o \u2014 o mesmo momento em que a verifica\xe7\xe3o\\nestrutural de conformidade recusaria, para que as duas verifica\xe7\xf5es (estrutural e\\nlegal) ocorram juntas.","A mensagem lista os c\xf3digos das regras reprovadas. \xc9 a mesma avalia\xe7\xe3o \u2014\\nmesmo reposit\xf3rio de obrigatoriedades, mesmo avaliador \u2014 que a consulta\\np\xfablica de conformidade legal exp\xf5e como leitura: a regra que a consulta\\nmostra reprovada \xe9 exatamente a que bloqueia a transi\xe7\xe3o."],"comoResolver":["Consulte `GET /api/selecao/processos-seletivos/{id}/conformidade-legal?dataReferencia={periodoInscricaoInicio}`\\n\u2014 informando a **mesma data de in\xedcio do per\xedodo de inscri\xe7\xe3o** que a\\ntransi\xe7\xe3o usaria \u2014 para ver, com o mesmo veredito, quais obrigatoriedades\\nlegais est\xe3o vigentes para o tipo do processo e qual delas reprovou. Uma data\\nde refer\xeancia diferente (por exemplo, a data de hoje) pode aprovar regras que\\na transi\xe7\xe3o recusaria, ou vice-versa. Ajuste a configura\xe7\xe3o do processo para\\natender a cada regra reprovada.","Se a regra em si estiver incorreta \u2014 por exemplo, vigente para o tipo de\\nprocesso errado, ou com a data de in\xedcio/fim mal ajustada \u2014, a corre\xe7\xe3o \xe9 no\\ncadastro de obrigatoriedades legais, n\xe3o na configura\xe7\xe3o deste processo."],"ondeAparece":["Publica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);